local config = {
  ui_story_30760401_1_1_dialog_content = "¿Estabas mintiendo cuando dijiste \"<color=#FFB400>La Sombra inundará este lugar</color>\", Señor Estafador?",
  ui_story_30760401_1_2_dialog_content = "Por supuesto, dije eso de manera indirecta a propósito, para hacer las cosas más interesantes.",
  ui_story_30760401_1_3_dialog_content = "Eso pensé. De todos modos, vine como tu me lo pediste, así que si tienes algo que decir, dilo.",
  ui_story_30760401_1_4_dialog_content = "Bien entonces, vamos a un lugar un poco más callado.",
  ui_story_30760401_1_5_dialog_content = "Soy un hombre sencillo con un propósito sencillo, estoy aburrido y no hay nada que hacer por aquí. Ahí es donde tu entras.",
  ui_story_30760401_1_6_dialog_content = "Normalmente te causaría algún problema. Esta vez quiero evitar eso, por eso te he llamado aquí.",
  ui_story_30760401_1_7_dialog_content = "Ya veo. Querías que yo viniera acá simplemente para aliviar tu aburrimiento. Y si yo me rehusará, ¿encontrarías otra manera de causar problemas?",
  ui_story_30760401_1_8_dialog_content = "Bingo.",
  ui_story_30760401_1_9_dialog_content = "Entonces, ¿por qué de repente eres tan honesto sobre esto?... De todos modos, si hay algo con lo que pueda ayudarte, no dudes en preguntarme.",
  ui_story_30760401_1_10_dialog_content = "Juguemos un pequeño <color=#FFB400>juego de adivinanzas</color>, Navegador, usando tus habilidades psíquicas.",
  ui_story_30760401_1_11_dialog_content = "No sabía que mi habilidad podría ser usada para juegos y divertirse...¿Qué debo adivinar?",
  ui_story_30760401_1_12_dialog_content = "Déjame ver... Para la primer ronda, dime ¿cuando el <color=#FFB400>pajarito</color> detrás de la puerta se ira?",
  ui_story_30760401_1_13_dialog_content = "¿Pajarito atrás de la puerta? Veo un pedazo de tela verde. ¿Es esa <color=#FFB400>Dove</color>?",
  ui_story_30760401_1_14_option_content = "Yo digo que el pajarito se irá pronto.",
  ui_story_30760401_1_15_dialog_content = "Después de todo, Dove usualmente está ocupada. Incluso si trata de holgazanear, no se puede dar el lujo de quedarse por mucho tiempo.",
  ui_story_30760401_1_16_dialog_content = "<color=#e8d9bb>Al poco tiempo...</color>",
  ui_story_30760401_1_17_dialog_content = "Parece que el pajarito no tiene planes de irse.",
  ui_story_30760401_1_18_dialog_content = "Bueno, como un pequeño castigo, ¿qué tal si la espantas?",
  ui_story_30760401_1_19_option_content = "Yo digo que el pajarito no se irá pronto.",
  ui_story_30760401_1_20_dialog_content = "Dove disfruta holgazanear.",
  ui_story_30760401_1_21_dialog_content = "Al poco tiempo...",
  ui_story_30760401_1_22_dialog_content = "Parece que el pajarito no tiene planes de irse.",
  ui_story_30760401_1_23_dialog_content = "Bueno, parece que tenías razón. Como castigo, iré a espantar al pajarito.",
  ui_story_30760401_1_24_dialog_content = "¿Por qué de repente hay un castigo? ¿Por qué espantar a Dove?",
  ui_story_30760401_1_25_dialog_content = "Mira, su capa está temblando. ¡Obviamente te tiene miedo!",
  ui_story_30760401_1_26_dialog_content = "Se interpondrá en el camino de otras personas saliendo y entrando por la puerta y no quiero que escuche nuestra siguiente conversación.",
  ui_story_30760401_1_27_dialog_content = "No, no es necesario. Yo...",
  ui_story_30760401_1_28_dialog_content = "¡Dove, no le hagas caso!",
  ui_story_30760401_1_29_dialog_content = "¿De verdad? Por tu propia seguridad, niña, te aconsejo no escuchar a escondidas.",
  ui_story_30760401_1_30_dialog_content = "No escucho a escondidas, ¡Solo estoy holgazaneando, quiero decir, descansando!",
  ui_story_30760401_1_A1_dialog_content = "¡Boo-hoo! ¡Me hiciste una injusticia!",
  ui_story_30760401_1_31_dialog_content = "¡Eso es ir muy lejos! ¡Voy a ganarte en este juego como venganza por Dove!",
  ui_story_30760401_1_32_dialog_content = "Está bien, continuemos. Tu segunda predicción... ¿Este cuarto está <color=#FFB400>limpio</color> o <color=#FFB400>sucio</color>?",
  ui_story_30760401_1_33_dialog_content = "No se requiere una pre cognición. Los auxiliares en el Colossus se encargan de la limpieza.",
  ui_story_30760401_1_34_dialog_content = "¿Qué son?",
  ui_story_30760401_1_35_dialog_content = "Son dispositivos que pueden hacer todo tipo de tareas por mí, como ir a los Generadores para colectar energía.",
  ui_story_30760401_1_36_option_content = "Este cuarto debe estar limpio.",
  ui_story_30760401_1_37_dialog_content = "¿Por qué está tan sucio aquí?",
  ui_story_30760401_1_38_dialog_content = "Esta pequeña esquina... Tal vez no la han limpiado.",
  ui_story_30760401_1_39_option_content = "Supongo, podría estar más limpia.",
  ui_story_30760401_1_40_dialog_content = "Es cierto. Las esquinas están sucias.",
  ui_story_30760401_1_41_dialog_content = "PlayerName, por favor límpialo ahora. Naturalmente, ayudaré.",
  ui_story_30760401_1_42_dialog_content = "¿Espera? ¿Por qué?",
  ui_story_30760401_1_43_dialog_content = "Porque mis tentáculos odian el polvo, han querido levantar el infierno.",
  ui_story_30760401_1_44_dialog_content = "Está bien. Así que por favor... pongamos a descansar esa amenaza.",
  ui_story_30760401_1_45_dialog_content = "<color=#e8d9bb>Después de una sesión meticulosa de limpieza</color>",
  ui_story_30760401_1_46_dialog_content = "Cuando dijiste que ayudarías, ¡no pensé que era solo estar parado rociando un poco de agua con tus tentáculos!",
  ui_story_30760401_1_47_dialog_content = "Bueno, pensé que estabas haciendo un excelente trabajo que no quería meterme en tu camino.",
  ui_story_30760401_1_48_dialog_content = "Entonces, para la tercera predicción, <color=#FFB400>preparemos algo para algunos transeúntes que puedan venir por aquí</color>.",
  ui_story_30760401_1_49_dialog_content = "¿Transeúntes?",
  ui_story_30760401_1_50_dialog_content = "Sí. Sin saber quien vaya a aparecer, cada uno colocamos un <color=#FFB400>regalo</color> en esta mesa.",
  ui_story_30760401_1_51_dialog_content = "Luego le preguntamos al transeúnte que elija uno para llevarse.",
  ui_story_30760401_1_52_dialog_content = "Ya veo. ¿Necesitamos adivinar quien va a aparecer?",
  ui_story_30760401_1_53_dialog_content = "Voy a empezar yo. Primero, alguna tela lujosa de terciopelo. Luego, una candela, rosas, un vino fino.",
  ui_story_30760401_1_54_dialog_content = "¡Espera! ¿De dónde sacaste todas estas cosas? No recuerdo haber visto estos en el Colossus.",
  ui_story_30760401_1_55_dialog_content = "Hay muchos lugares para guardar cosas. En mi sombrero, capa, tentáculos.",
  ui_story_30760401_1_56_dialog_content = "No me interesa donde los obtuviste, ¿no es esto hacer trampa? ¿Qué no dijiste un regalo?",
  ui_story_30760401_1_57_dialog_content = "Puedes estar seguro que acataré las reglas, lo prometo. El único regalo que ofreceré es este <color=#FFB400>fino vino rojo</color>.",
  ui_story_30760401_1_58_dialog_content = "En términos de valor y gusto, es el mejor vino disponible, usado únicamente para entretener los más distinguidos invitados.",
  ui_story_30760401_1_59_dialog_content = "Los otros artículos solo están aquí para rellenar la mesa y hacer ver el vino más como un regalo—",
  ui_story_30760401_1_60_dialog_content = "<color=#FFB400>Por favor haz una nota de este punto</color>",
  ui_story_30760401_1_61_dialog_content = "¿Qué estás preparando?",
  ui_story_30760401_1_62_dialog_content = "(¿Un regalo...? No tengo nada de valor conmigo...)",
  ui_story_30760401_1_63_dialog_content = "(¡Mi única ventaja es saber que hay más niñas en este Colossus que niños!)",
  ui_story_30760401_1_64_option_content = "Coloca un lápiz en la mesa",
  ui_story_30760401_1_65_dialog_content = "<color=#e8d9bb>Al poco tiempo...</color>",
  ui_story_30760401_1_66_dialog_content = "¿Ah? ¿Quieres que escoja uno de estos dos regalos? ¿Puedo tomar uno...?",
  ui_story_30760401_1_67_dialog_content = "No me gusta el vino, así que tomaré esto.",
  ui_story_30760401_1_68_dialog_content = "(Como era de esperarse, ¡Vice escoge el regalo que yo prepare!)",
  ui_story_30760401_1_69_dialog_content = "Parece que ganaste.",
  ui_story_30760401_1_70_option_content = "Coloca algunos postres en la mesa",
  ui_story_30760401_1_71_dialog_content = "<color=#e8d9bb>Al poco tiempo...</color>",
  ui_story_30760401_1_72_dialog_content = "¿Un regalo?",
  ui_story_30760401_1_73_dialog_content = "Hmm... Bien... Supongo que será esto...",
  ui_story_30760401_1_74_dialog_content = "Una chica alada pasa por delante. Aunque lo duda, eventualmente toma los postres que tu preparaste.",
  ui_story_30760401_1_75_dialog_content = "Parece que ganaste.",
  ui_story_30760401_1_76_dialog_content = "Así que, ahora para la </color=#FFB400>última predicción</color>, la cuál también es la más importante. Por favor escucha con cuidado—",
  ui_story_30760401_1_77_dialog_content = "<color=#FFB400>¿Quién será el próximo en entrar a este cuarto?</color>",
  ui_story_30760401_1_78_dialog_content = "¿De nuevo? ¿Cómo se supone que adivine eso? ¿No es eso un poco difícil?",
  ui_story_30760401_1_79_dialog_content = "La última vez se trataba de pasar, ahora es acerca de entrar. Como dueño del Colossus, tu deberías de conocer a todos abordo.",
  ui_story_30760401_1_80_dialog_content = "De hecho, justo ahora hiciste un bueno trabajo.",
  ui_story_30760401_1_81_dialog_content = "Bueno, déjame pensarlo primero.",
  ui_story_30760401_1_82_dialog_content = "Claro, los dos necesitamos un poco de tiempo para pensarlo.",
  ui_story_30760401_1_83_dialog_content = "(Bueno, de acuerdo con la lógica ahora)",
  ui_story_30760401_1_84_option_content = "Yo creo.",
  ui_story_30760401_1_85_dialog_content = "¿Eh? ¿Dónde está Kleken? ¡Solo miré hacia abajo un momento y ha desaparecido!",
  ui_story_30760401_1_86_dialog_content = "¿Fue afuera...? ¿Esta intentando hacer trampa?",
  ui_story_30760401_1_87_dialog_content = "Bueno, es muy lindo aquí. Originalmente había planeado venir por una visita casual... No esperaba que fueras<color=#FFB400>tan considerado</color>.",
  ui_story_30760401_1_88_dialog_content = "(¡¿S-S-Señor Sombrío?!)",
  ui_story_30760401_1_89_dialog_content = "Es tranquilo y disfruto mi privacidad. <color=#FFB400>No hay nadie reunido en mi puerta</color>. Un buen lugar, bien hecho.",
  ui_story_30760401_1_90_dialog_content = "Yo, yo solo.",
  ui_story_30760401_1_91_dialog_content = "Incluso el piso está impecable. ¿<color=#FFB400>Se limpiaron las esquinas también</color>?",
  ui_story_30760401_1_92_dialog_content = "(Esto quiere decir)",
  ui_story_30760401_1_93_dialog_content = "<color=#FFB400> Un mantel de terciopelo, vino rojo...</color> Has estado preguntando por mis cosas favoritas, ¿no?",
  ui_story_30760401_1_94_dialog_content = "Realmente eres interesante, PlayerName.",
  ui_story_30760401_1_95_dialog_content = "(¿¡Kleken preparó esto en secreto todo el tiempo!?)",
  ui_story_30760401_1_96_dialog_content = "(¿¡No podías decirme que Istvan venía a visitar!?)",
  ui_story_30760401_1_97_dialog_content = "Por supuesto, dije eso de manera indirecta a propósito, solo para hacer las cosas más interesantes.",
  ui_story_30760401_1_98_dialog_content = "(Ah... ¿Eso es lo que quiso decir...?)",
  ui_story_30760401_1_99_dialog_content = "Bien. Puedo ver tu seriedad. Entonces creo que no me decepcionarás en la conversación que estamos a punto de tener.",
  ui_story_30760401_1_100_dialog_content = "¿Eh? ¿¡Qué—!?",
  ui_story_30760301_1_1_dialog_content = "¿Qué hago con este <color=#FFB400>Mapa de Dibury</color>? Realmente no tengo idea.",
  ui_story_30760301_1_2_dialog_content = "Es muy simple. Sacas una carta de clase después de seleccionar una pieza.",
  ui_story_30760301_1_3_dialog_content = "Saqué la carta de clase Civil.",
  ui_story_30760301_1_4_dialog_content = "Suertudo, saque la carta de Estafador.",
  ui_story_30760301_1_5_dialog_content = "Espera... ¿Al menos esta esa carta en este juego? No haces trampa, ¿verdad?",
  ui_story_30760301_1_6_dialog_content = "Claro que no. Míralo tu mismo.",
  ui_story_30760301_1_7_dialog_content = "Hmm,<color=#FFB400>realmente dice Estafador en la carta</color>...",
  ui_story_30760301_1_8_dialog_content = "Hemos encontrado matones. Es hora de tirar los dados. Necesitas que ambas la Estrategia y Combate sean más altas que 6.",
  ui_story_30760301_1_9_dialog_content = "¡Estrategia 8, Combate 9! ¡Lo logré!",
  ui_story_30760301_1_10_dialog_content = "¡Estrategia 13, Combate 4! Parece que tendré que sacar una carta de Evento.",
  ui_story_30760301_1_11_dialog_content = "La carta de Evento dice: “Tu documento secreto ha sido confiscado y te arrojan a un calabozo.”",
  ui_story_30760301_1_12_dialog_content = "Cada vez que veo esto, siempre me recuerda a <color=#FFB400>una experiencia pasada</color>. ¿Te gustaría oír sobre ella?",
  ui_story_30760301_1_13_option_content = "Cuéntame.",
  ui_story_30760301_1_14_dialog_content = "Pareces ansioso. Tendré que hacer un mejor trabajo contándolo.",
  ui_story_30760301_1_15_option_content = "No estoy interesado. ¿Por qué de repente me cuentas una historia?",
  ui_story_30760301_1_16_dialog_content = "Bueno, eso no servirá. Confía en mí, es una buena historia. Me temo que te tendré que obligar a escuchar.",
  ui_story_30760301_1_17_dialog_content = "<color=#e8d9bb>En una cavidad subterránea enterrada por escombros</color>",
  ui_story_30760301_1_18_dialog_content = "Si debo morir así, que así sea. Es solo que...",
  ui_story_30760301_1_19_dialog_content = "¿Hay alguien ahí? ¡Ayúdanos!",
  ui_story_30760301_1_20_dialog_content = "Niños, no se reúnan alrededor de mis pies.",
  ui_story_30760301_1_21_dialog_content = "¡Tenemos miedo!",
  ui_story_30760301_1_22_dialog_content = "No te muevas. Hay un agujero aquí.",
  ui_story_30760301_1_24_dialog_content = "¿Eres el Señor Sombrío?",
  ui_story_30760301_1_25_dialog_content = "No lo soy. Pueden llamarme Kleken, o Estafador.",
  ui_story_30760301_1_26_dialog_content = "¿Qué hacemos ahora, Sr. Swindler?",
  ui_story_30760301_1_27_dialog_content = "Podríamos jugar por un rato. Tengo algo aquí. Da la casualidad de que he traído este <color=#FFB400>Mapa de Dibury</color>. Mejor que estar sentado haciendo nada.",
  ui_story_30760301_1_28_dialog_content = "¡Wow, eso es increíble! ¿Por qué tienes este juego?",
  ui_story_30760301_1_29_dialog_content = "Traje muchas cosas cuando venía hacía acá.",
  ui_story_30760301_1_30_dialog_content = "¡Espera un segundo!",
  ui_story_30760301_1_31_dialog_content = "¿Cuál es el punto de este recuerdo aleatorio?",
  ui_story_30760301_1_32_dialog_content = "Es una historia sobre las pequeñas niñas y yo enterrados bajo tierra.",
  ui_story_30760301_1_33_dialog_content = "No, no, yo quiero saber quienes son las pequeñas niñas y ¿a qué te referías sobre gatear en tus pies?",
  ui_story_30760301_1_34_dialog_content = "¿Por qué sacar el mapa de Dibury? ¿Y a qué te refieres con lo de comprar un lote en el camino?",
  ui_story_30760301_1_35_dialog_content = "Bueno, déjame empezar desde el principio.",
  ui_story_30760301_1_36_dialog_content = "<color=#e8d9bb>Hace un año...</color>",
  ui_story_30760301_1_37_dialog_content = "¿Has escuchado acerca de los <color=#FFB400>matones</color> en el borde de Umbraton?",
  ui_story_30760301_1_38_dialog_content = "Yo sé.",
  ui_story_30760301_1_39_dialog_content = "Han secuestrado a dos niñas con asociación a nuestra organización y me han pedido negociar con ellos.",
  ui_story_30760301_1_40_dialog_content = "Pero debo atender hoy a una reunión celebrada por el Gremio, un hecho del que están bien informados.",
  ui_story_30760301_1_41_dialog_content = "Los matones no saben como me veo, entonces quiero que tu trates con esto en vez de mí. Después de todo, tienes mucha experiencia en el arte del engaño.",
  ui_story_30760301_1_42_dialog_content = "¿Quieres que te imite? Interesante. Lo tengo.",
  ui_story_30760301_1_43_dialog_content = "Ya sea papel o comida, trae todo lo que necesites. Hay un poco de carne y pan en la mesa. Tómalo.",
  ui_story_30760301_1_44_dialog_content = "¿Eres el líder de la Pandilla Istvan?",
  ui_story_30760301_1_45_dialog_content = "¿Dónde están los rehenes? Me aseguraré que estén a salvo.",
  ui_story_30760301_1_46_dialog_content = "Se están relajando por allí. No te preocupes, tenemos algo para entretener a tus niñas.",
  ui_story_30760301_1_48_dialog_content = "Dime que quieres para soltarlas. La pelota está en tu cancha.",
  ui_story_30760301_1_49_dialog_content = "Solo firma este documento y las dejaré ir.",
  ui_story_30760301_1_51_dialog_content = "“Transferencia de Derechos”...",
  ui_story_30760301_1_52_dialog_content = "Sin problema. Firmado.",
  ui_story_30760301_1_53_dialog_content = "Eres tan precipitado. ¿Estás seguro que lo leíste con cuidado?",
  ui_story_30760301_1_54_dialog_content = "Dice que los derechos de la Pandilla Istvan de cooperar con el Gremio serán transferidos a ti.",
  ui_story_30760301_1_55_dialog_content = "Decidiste hacer este secuestro el día de hoy para sabotear la reunión entre la Pandilla Istvan y el Gremio, ¿verdad?",
  ui_story_30760301_1_56_dialog_content = "Correcto. Es refrescante poder hablar con alguien tan intuitivo. Definitivamente eres digno de estar a cargo de la Pandilla Istvan.",
  ui_story_30760301_1_57_dialog_content = "Espera... ¿¡Desde cuando el Señor Sombrío tiene hijas!?",
  ui_story_30760301_1_58_dialog_content = "Claro que no tiene. Quizás habían reunido información engañosa de algún lugar, de ahí el malentendido.",
  ui_story_30760301_1_59_dialog_content = "Permíteme continuar con la historia.",
  ui_story_30760301_1_60_dialog_content = "Sí, todos firmados.",
  ui_story_30760301_1_61_dialog_content = "Ahora que lo firmaste como lo solicitamos. Los rehenes están en esa cabaña. Siéntete libre de llevártelos.",
  ui_story_30760301_1_62_dialog_content = "Entonces, ¿los matones te permitieron llevarte las rehenes e irte?",
  ui_story_30760301_1_63_dialog_content = "¿Qué harías si estuvieras en su posición? ¿Nos dejarías ir?",
  ui_story_30760301_1_64_option_content = "Los dejaría ir, como se acordó.",
  ui_story_30760301_1_65_dialog_content = "Después de todo, firmaste el trato, como se solicitó. Si no les deja ir, mi credibilidad se arruinaría.",
  ui_story_30760301_1_66_dialog_content = "A los matones no les importa la credibilidad.",
  ui_story_30760301_1_67_option_content = "Claro que no te dejaría ir.",
  ui_story_30760301_1_68_dialog_content = "Si tomas represalias o rompes el acuerdo después, el secuestro habría sido en vano.",
  ui_story_30760301_1_69_dialog_content = "Si el Señor Sombrío hubiera firmado el trato, la Pandilla Istvan nunca hubiera roto su promesa. A eso es a lo que llamas credibilidad.",
  ui_story_30760301_1_70_dialog_content = "Y ¿realmente fuiste a la cabaña? ¿No tenías miedo de que hayan puesto una trampa?",
  ui_story_30760301_1_71_dialog_content = "Tuve que entrar. La seguridad de los rehenes era mi prioridad.",
  ui_story_30760301_1_72_dialog_content = "¿Qué pasó después?",
  ui_story_30760301_1_73_dialog_content = "Cuando entre a desatar a los rehenes, encontré a dos niñas durmiendo. Y luego...",
  ui_story_30760301_1_74_dialog_content = "<size=50>¡Boom!</size>",
  ui_story_30760301_1_75_dialog_content = "¡Detonaron una bomba subterránea!",
  ui_story_30760301_1_76_dialog_content = "¿Una bomba? ¿Algún herido?",
  ui_story_30760301_1_77_dialog_content = "¿Aquí es donde comienza la historia de ti y las niñas enterradas en escombros?",
  ui_story_30760301_1_78_dialog_content = "Sí. Aunque la explosión no fue tan grande, de todas formas gasté gran parte de mi fuerza para defenderme completamente.",
  ui_story_30760301_1_79_dialog_content = "No pudimos salir de inmediato, ya que necesitaba tiempo para recuperarme.",
  ui_story_30760301_1_80_dialog_content = "Está bien... ¿Pero dijiste que sacaste el Mapa de Dibury? ¿Realmente terminaron jugando en él?",
  ui_story_30760301_1_81_dialog_content = "Lo hicimos. Pero poco después de que comenzamos, se tragaron los dados, así que tuvimos que charlar en esas ruinas subterráneas.",
  ui_story_30760301_1_82_dialog_content = "Me parece que te uniste a la pandilla Istvan no hace mucho.",
  ui_story_30760301_1_83_dialog_content = "Oh, nos reconoces. Somos <color=#FFB400>Patty</color> y <color=#FFB400>Patsy</color>.",
  ui_story_30760301_1_84_dialog_content = "¿Cómo las atraparon? No se ven particularmente fuertes...",
  ui_story_30760301_1_85_dialog_content = "Estábamos jugando y luego nos desmayamos de hambre al costado de la carretera. Cuando abrimos los ojos, ya estábamos secuestrados.",
  ui_story_30760301_1_86_dialog_content = "No es de extrañar que siempre estén en el suelo. El Señor Sombrío seguro preparó esta comida para ustedes.",
  ui_story_30760301_1_87_dialog_content = "¡Carne!",
  ui_story_30760301_1_88_dialog_content = "¡Pan!",
  ui_story_30760301_1_89_dialog_content = "Nom, nom...",
  ui_story_30760301_1_90_dialog_content = "¡Estamos llenos!",
  ui_story_30760301_1_91_dialog_content = "Manos a la obra. Retrocede un poco... Debo limpiar los escombros arriba de nosotros.",
  ui_story_30760301_1_92_dialog_content = "¡Qué grandes y poderosos tentáculos! ¿De dónde salieron?",
  ui_story_30760301_1_93_dialog_content = "Eso no importa. <color=#FFB400>Solo tómalo como un espejismo</color>. Ahora es tu turno de sudar...",
  ui_story_30760301_1_94_dialog_content = "Probablemente solo hay unos pocos matones protegiendo su base. Yo sé donde están. Vamos a morderlos.",
  ui_story_30760301_1_95_dialog_content = "Luego, tomamos su base fácilmente. Final feliz.",
  ui_story_30760301_1_96_dialog_content = "Espera... Cielos, ¡ahora me tienes diciéndolo!",
  ui_story_30760301_1_97_dialog_content = "¿Por qué crees que solo hay un par de matones cuidando su base?",
  ui_story_30760301_1_98_dialog_content = "Sencillo, porque su jefe fue al Gremio con sus lacayos y el acuerdo.",
  ui_story_30760301_1_99_dialog_content = "¿El arreglo que firmaste? Eso no debe haber pasado por ser legítimo.",
  ui_story_30760301_1_100_dialog_content = "No, use el nombre y sello de Istvan al firmar.",
  ui_story_30760301_1_101_dialog_content = "Ese documento si era válido, lamentablemente...",
  ui_story_30760301_1_102_dialog_content = "<color=#e8d9bb>En la reunión secreta</color>",
  ui_story_30760301_1_103_dialog_content = "¿Quiénes son y que hacen aquí extraños?",
  ui_story_30760301_1_104_dialog_content = "¿Eres el jefe del Gremio? Ahora, nuestra pandilla trabajara para ti.",
  ui_story_30760301_1_105_dialog_content = "Aquí está la “Transferencia de Derechos”, firmada por Istvan.",
  ui_story_30760301_1_106_dialog_content = "¿Un acuerdo? ¿No es ese el <color=#FFB400>Mapa de Dibury</color>? Es del mismo lote que pusimos afuera recientemente.",
  ui_story_30760301_1_107_dialog_content = "Pero claramente está escrito en este papel que... ¡De ninguna manera! ¡<color=#FFB400>Esto debe ser un espejismo</color>!",
  ui_story_30760301_1_108_dialog_content = "¡Diablos! ¿¡Istvan nos engañó!? ¿¡Cómo!?",
  ui_story_30760301_1_109_dialog_content = "El Sr. Istvan esta aquí con un grupo de asistentes. ¿Te gustaría conocerlo?",
  ui_story_30760301_1_110_dialog_content = "Has venido hasta aquí. Por favor, toma asiento...",
  ui_story_30760301_1_111_dialog_content = "Entonces los matones fueron enviados directo a las manos del Señor Sombrío. Final feliz de nuevo.",
  ui_story_30760301_1_112_dialog_content = "¿Los matones se llevaron el Mapa de Dibury? ¿Cómo lo confundieron con un acuerdo?",
  ui_story_30760301_1_113_dialog_content = "Lo confirmaron una y otra vez. Si hubieras sido tú, ¿habrías sido engañado por mi treta?",
  ui_story_30760301_1_114_option_content = "Bueno, si tu hubieras sido el que lo dio... ¿Tal vez?",
  ui_story_30760301_1_115_dialog_content = "Parece que al menos me conoces un poco.",
  ui_story_30760301_1_116_option_content = "¡No puede ser! ¡Habría sido capaz de decirlo!",
  ui_story_30760301_1_117_dialog_content = "No es malo tener tanta confianza.",
  ui_story_30760301_1_118_dialog_content = "Bueno, echa un vistazo a esto.",
  ui_story_30760301_1_119_dialog_content = "¿Eh? ¿Esta no es la carta de clase que sacaste al inicio?",
  ui_story_30760301_1_120_dialog_content = "¿Qué hay ahí?",
  ui_story_30760301_1_121_dialog_content = "Mmm... ¿Clase <color=#FFB400>Gangster</color>? ¿¡Cómo es eso posible!?",
  ui_story_30760301_1_122_dialog_content = "¡Pero claramente decía <color=#FFB400>Estafador</color> antes! ¿Hiciste trampa y cambiaste las cartas?",
  ui_story_30760301_1_123_dialog_content = "No, no hay Estafador en el juego del Mapa de Dibury para empezar.",
  ui_story_30760301_1_124_dialog_content = "<color=#FFB400>Lo que viste antes... Solo tómalo como un espejismo</color>",
  ui_story_30760601_1_1_dialog_content = "El sol abrasador, la arena ardiente...",
  ui_story_30760601_1_2_dialog_content = "Algo no se siente muy bien... <color=#FFB400>Ese ideal</color>... es realmente sospechoso...",
  ui_story_30760601_1_3_dialog_content = "Entonces por qué estoy... corriendo en un día tan caliente...",
  ui_story_30760601_1_4_dialog_content = "Y haciendo entregas en el lugar de ¡¿<color=FFB400>Kleken</color>?!",
  ui_story_30760601_1_5_dialog_content = "¡Kleken!",
  ui_story_30760601_1_6_dialog_content = "¡Ey, hola, volviste! ¿Terminaste con la entrega?",
  ui_story_30760601_1_7_dialog_content = "Sí, lo hice... Tú...",
  ui_story_30760601_1_8_dialog_content = "¿Quién eres tú?",
  ui_story_30760601_1_9_dialog_content = "Aww... Pobre cosita, llevas todo el día corriendo por la playa haciendo entregas para mí.",
  ui_story_30760601_1_10_dialog_content = "Parece que el calor se te está subiendo a la cabeza. Ni siquiera recuerdas por quién te estabas tan preocupado...",
  ui_story_30760601_1_11_dialog_content = "¿Quién más estaría aquí, además de mí?",
  ui_story_30760601_1_12_dialog_content = "¡¿K-Kleken?!¡¿Siempre te has visto tan joven?!",
  ui_story_30760601_1_13_dialog_content = "¡Felicidades! Te has topado con otra verdad.",
  ui_story_30760601_1_14_dialog_content = "Cuando hace este calor, <color=#FFB400>me convierto en un Kleken completamente diferente</color>.",
  ui_story_30760601_1_15_dialog_content = "Ahora bien, ¿por qué no te sientas y te tomas un descanso? ¿agua?",
  ui_story_30760601_1_16_dialog_content = "Aún tengo algunas cosas que quiero que entregues.",
  ui_story_30760601_1_17_dialog_content = "No... ¡De ninguna manera! ¡No te estoy ayudando a entregar nada! ¡Hazlo tú mismo!",
  ui_story_30760601_1_18_dialog_content = "Ya, PlayerName, no hace falta que me chasquees así. Después de todo, tú eres quien me prometió ayudarme a “terminar mis asuntos incompletos.”",
  ui_story_30760601_1_19_dialog_content = "Si lo has olvidado, no me importaría refrescarte un poco la memoria...",
  ui_story_30760601_1_20_dialog_content = "¡Q-quédate atrás! Puedo averiguar cómo me has engañado yo solo, ¡gracias!",
  ui_story_30760601_1_21_dialog_content = "¿Has oído alguna vez la historia del héroe que fue al palacio submarino y derrotó a un enorme monstruo marino? Esa es una muy linda historia.",
  ui_story_30760601_1_22_dialog_content = "Por eso creo que deberías cuidar tu lado izquierdo también, pequeño héroe...",
  ui_story_30760601_1_23_dialog_content = "¡Graagh!",
  ui_story_30760601_1_24_dialog_content = "Por fin... he terminado...",
  ui_story_30760601_1_25_dialog_content = "Entonces, ¡¿por qué he estado aguantando este tipo de peligro todo este tiempo?!",
  ui_story_30760601_1_26_dialog_content = "Para ayudarme a adquirir estos productos tan importantes, por supuesto.",
  ui_story_30760601_1_27_dialog_content = "No, pensé que sólo te habías encontrado con algunos pequeños problemas mientras te preparabas para el Soberano del Océano...",
  ui_story_30760601_1_28_dialog_content = "Así que me pediste ayuda...",
  ui_story_30760601_1_29_dialog_content = "¡¿Quién iba a imaginar que me harías encontrar Eclipsites, y que luego me arrastrarías a una multitud de ellas?!",
  ui_story_30760601_1_30_dialog_content = "...",
  ui_story_30760601_1_31_dialog_content = "Oye, ¿por qué estás tan callado? ¿No vas a explicarte?",
  ui_story_30760601_1_32_dialog_content = "Discúlpame... ¿Qué explicaciones quieres? Voy a dejar esto por un segundo...",
  ui_story_30760601_1_33_dialog_content = "¿Estás... bien?",
  ui_story_30760601_1_34_dialog_content = "Estoy bien. Casi me caigo, eso es todo.",
  ui_story_30760601_1_35_dialog_content = "(¿Cómo puede alguien tan ágil como Kleken \"casi caerse\"? Es él...)",
  ui_story_30760601_1_36_dialog_content = "¿Estás sudando?",
  ui_story_30760601_1_37_dialog_content = "Por supuesto que sí... Hace mucho calor, después de todo...",
  ui_story_30760601_1_38_dialog_content = "Y aún así llevas una ropa tan gruesa... Has quemado toda esa energía luchando contra esas Eclipsites con un traje completo hace un momento.",
  ui_story_30760601_1_39_dialog_content = "Pero más importante...¿Te lastimaste en esa pelea?",
  ui_story_30760601_1_40_dialog_content = "Eh... Parece que el gato salió de la bolsa. Nada mal, PlayerName.",
  ui_story_30760601_1_41_dialog_content = "Lo siento... No me siento como yo mismo...",
  ui_story_30760601_1_42_dialog_content = "Lo siento mucho... Pero no creo que pueda terminar esto solo...",
  ui_story_30760601_1_43_dialog_content = "A decir verdad, es la primera vez que te veo arriesgar tu vida así por un trabajo...",
  ui_story_30760601_1_44_dialog_content = "¿Qué tomaste de los Eclipsites?",
  ui_story_30760601_1_45_dialog_content = "Ábrelas y lo sabrás. Adelante, abre algunas de estas cajas y echa un vistazo a lo que hay dentro.",
  ui_story_30760601_1_46_dialog_content = "Pues...",
  ui_story_30760601_1_47_dialog_content = "¿Qué es esto, una caja llena de tela?",
  ui_story_30760601_1_48_dialog_content = "Es una caja llena de mercancía valiosa.",
  ui_story_30760601_1_49_dialog_content = "¿\"Mercancía valiosa\"?¿Me estás diciendo que les han robado los Eclipsites?",
  ui_story_30760601_1_50_dialog_content = "Esto no es sólo un trabajo, tiene que ver con mis ideales... con los palacios de nuestros corazones.",
  ui_story_30760601_1_51_dialog_content = "Pero ya no tengo forma de entregar esta mercancía a los comerciantes de Umbraton...",
  ui_story_30760601_1_52_dialog_content = "Y van a sufrir por ello, estoy seguro.",
  ui_story_30760601_1_53_dialog_content = "Cuando lo pienso así, mi conciencia amenaza con desgarrarme.",
  ui_story_30760601_1_54_dialog_content = "¡Deja ya de hablar de tus ideales!",
  ui_story_30760601_1_55_dialog_content = "¡Yo llevaré las cajas!¡Salgamos de aquí antes de que nos encuentren más Eclipsites!",
  ui_story_30760601_1_56_dialog_content = "No... Sigue adelante. Hay una persona en el lado sur de la playa, entrégala en la próxima media hora.",
  ui_story_30760601_1_57_dialog_content = "Eso no debería ser un problema para ti. Dada tu velocidad, ¡creo que llegarás a tiempo!",
  ui_story_30760601_1_58_dialog_content = "Toma, cógelo y corre. Sigue corriendo hacia adelante, y no vuelvas atrás.",
  ui_story_30760601_1_59_dialog_content = "Por favor... Asegúrate que esto llegue a las manos de esa persona.",
  ui_story_30760601_1_60_dialog_content = "¿Ah? ¿Pero qué hay de ti?",
  ui_story_30760601_1_61_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_62_dialog_content = "Yo los detendré en tu lugar...",
  ui_story_30760601_1_63_dialog_content = "¡¿Kleken?!",
  ui_story_30760601_1_64_dialog_content = "¡Apúrate, PlayerName! ¡Solo corre!",
  ui_story_30760601_1_65_dialog_content = "¡Graagh!",
  ui_story_30760601_1_66_dialog_content = "Y así, el valiente guerrero corrió, llevando sus esperanzas hasta el destino final.",
  ui_story_30760601_1_67_dialog_content = "Y cuando se encontró con problemas, el monstruo marino blanco acudió a su rescate.",
  ui_story_30760601_1_68_dialog_content = "Sí... Suena como una historia maravillosa. En cuanto a su nombre...",
  ui_story_30760601_1_69_dialog_content = "Gaah... Graaah...",
  ui_story_30760601_1_70_dialog_content = "¿Cuánto más lejos? ¿Cuánto tiempo queda?",
  ui_story_30760601_1_71_dialog_content = "Se sacrificó sin dudarlo...¡Tengo que entregar estas cosas a esa persona!",
  ui_story_30760601_1_72_dialog_content = "Puedo hacerlo... ¡y luego traeré a otros conmigo para salvarlo!",
  ui_story_30760601_1_73_dialog_content = "*Jadeando para respirar* Yo... Finalmente lo logré...",
  ui_story_30760601_1_74_dialog_content = "¡Oh! ¡Finalmente estás aquí! ¡He estado esperando todo el día!",
  ui_story_30760601_1_75_dialog_content = "¡Esta mercancía es realmente importante!¿Eres tú a quien debo entregarla?",
  ui_story_30760601_1_76_dialog_content = "¡Claro que sí! Hmm, no está mal... Aquí, déjame echar un vistazo a lo que tenemos hoy.",
  ui_story_30760601_1_77_dialog_content = "¡Ya no hay tiempo! ¡Tenemos que volver y rescatar a Kleken! ¡Está rodeado de Eclipsites!",
  ui_story_30760601_1_78_dialog_content = "¿Ja? Pero el tendero de allí recibió un mensaje de Kleken hace menos de media hora. Él dijo...",
  ui_story_30760601_1_79_dialog_content = "Ha dicho que ya se ha ocupado de todo. Sólo hay que esperar a que aparezca con la mercancía.",
  ui_story_30760601_1_80_dialog_content = "¿Eh?¿Hace media hora?",
  ui_story_30760601_1_81_dialog_content = "¿No habría sido justo después de que me fuera?",
  ui_story_30760601_1_82_dialog_content = "También dijo que había encontrado a alguien muy eficiente para entregar la mercancía esta vez, y que no había que preocuparse. Tú eres la persona que mencionó, ¿supongo?",
  ui_story_30760601_1_83_dialog_content = "Aunque eres un poco lento. Según nuestras cuentas, deberías haber llegado hace diez minutos.",
  ui_story_30760601_1_84_dialog_content = "Ese tipo ha estado haciendo una fortuna con esta línea de trabajo. Debe estar bien pagado ya que trabaja para él, ¿eh?",
  ui_story_30760601_1_85_dialog_content = "¿Has dicho \"hacer una fortuna\"?¿Los Eclipsites no les robaron toda esta mercancía?",
  ui_story_30760601_1_86_dialog_content = "¿De qué rayos estás hablando? Sólo importamos estas cosas a través de Kleken, eso es todo...",
  ui_story_30760601_1_87_dialog_content = "Yo... Necesito regresar y llegar al fondo de esto.",
  ui_story_30760601_1_88_dialog_content = "¡Pensé que ibas a ser devorado por una turba de Eclipsites!",
  ui_story_30760601_1_89_dialog_content = "¡Pensé que me habías enviado para proteger algo que valorabas más que tu propia vida!",
  ui_story_30760601_1_90_dialog_content = "¡Pensé que estabas débil por el calor y tus heridas!",
  ui_story_30760601_1_91_dialog_content = "Me arriesgué al sol y al calor para entregar la mercancía, pero entonces ese mercader me dijo...",
  ui_story_30760601_1_92_dialog_content = "¡Qué no era su mercancía robada en absoluto!¿Has estado robando estas cosas a otras personas para venderlas a los mercaderes?",
  ui_story_30760601_1_93_dialog_content = "Cálmate, PlayerName. Todo esto es solo un malentendido. Déjame explicar...",
  ui_story_30760601_1_94_dialog_content = "Cuando vine aquí, y pedí su ayuda...",
  ui_story_30760601_1_95_dialog_content = "Fue porque tenía un trabajo muy importante que hacer, a saber, acabar con algunos Eclipsites.",
  ui_story_30760601_1_96_dialog_content = "De hecho, nos encontramos con algunos problemas mientras nos preparábamos para el Soberano del Océano: una turba de Eclipsites que se había atrincherado aquí.",
  ui_story_30760601_1_97_dialog_content = "Además, yo estaba realmente herido y no podía soportar el calor.",
  ui_story_30760601_1_98_dialog_content = "Estaba demasiado débil para hacer el trabajo, y tú me ayudaste a terminarlo. Yo debería dar gracias.",
  ui_story_30760601_1_99_dialog_content = "Pero cuando te pregunté si esas eran las mercancías de tus chicos, por qué...",
  ui_story_30760601_1_100_dialog_content = "Te lo dije, tiene que ver con <color=#FFB400>mis ideales</color>, y con los <color=#FFB400>palacios de nuestros corazones</color>.",
  ui_story_30760601_1_101_dialog_content = "¡¿Estabas esquivando la pregunta a propósito?!",
  ui_story_30760601_1_102_dialog_content = "¡Pensé que intentabas decir que la mercancía era importante para realizar tus sueños o algo así!",
  ui_story_30760601_1_103_dialog_content = "¡Incluso creí que estabas intentando ahorrar dinero para construir un palacio!",
  ui_story_30760601_1_104_dialog_content = "Jeje... Nada mal, PlayerName. Descubriste la verdad incluso más rápido de lo que había previsto.",
  ui_story_30760601_1_105_dialog_content = "Pero si realmente crees que hago todo esto por el dinero, estás muy equivocado.",
  ui_story_30760601_1_106_dialog_content = "De hecho, estoy actuando en interés de mis ideales.",
  ui_story_30760601_1_107_dialog_content = "¡¿Qué significa eso?! ¡Porque estoy, de hecho, convencido de que sólo me estás usando ganar dinero!",
  ui_story_30760601_1_108_dialog_content = "Me usaste para encontrar las Eclipsites, y me usaste para entregar la mercancía...",
  ui_story_30760601_1_X108_dialog_content = "Pero lo más importante es que ninguna de esas mercancías les pertenecía a ninguno de ustedes.",
  ui_story_30760601_1_X109_dialog_content = "¿Te has puesto a pensar en lo preocupados que pueden estar los dueños originales de esas mercancías ahora mismo?",
  ui_story_30760601_1_X110_dialog_content = "¿O crees que puedes empeñar todo lo que robas de Eclipsites?",
  ui_story_30760601_1_109_dialog_content = "Eso es suficiente. Según la investigación de la Pandilla Istvan sobre la mercancía, llegamos a la conclusión...",
  ui_story_30760601_1_110_dialog_content = "Que la mercancía <color=#FFB400>no tiene dueño original</color>.",
  ui_story_30760601_1_111_dialog_content = "Entonces, ¿intentas decir que esto no era un negocio sucio, para empezar?",
  ui_story_30760601_1_112_dialog_content = "Correcto Esta es una información muy importante, sin ella, definitivamente malinterpretarías mis intenciones.",
  ui_story_30760601_1_113_dialog_content = "Cuando recibo mi pago, es sólo para eliminar Eclipsites y nada más.",
  ui_story_30760601_1_114_dialog_content = "El resto va directamente a la Pandilla Istvan.",
  ui_story_30760601_1_115_dialog_content = "Puede que no lo sepas, pero el Señor Sombrío es bastante aficionado a realizar \"buenas acciones.\"",
  ui_story_30760601_1_116_dialog_content = "Okay...",
  ui_story_30760601_1_117_dialog_content = "Lo siento, admito que te malentendí un poco justo ahora.",
  ui_story_30760601_1_118_dialog_content = "No lo menciones.",
  ui_story_30760601_1_119_dialog_content = "Como estafador, prefiero que se desconfíe de mí a que se confíe en mí.",
  ui_story_30760601_1_120_dialog_content = "Por qué tengo la sensación de que estás siendo sarcástico...",
  ui_story_30760601_1_121_dialog_content = "¿Qué es ese \"ideal\" del que hablas? Dijiste que actuabas en interés de tus ideales, ¿no?",
  ui_story_30760601_1_122_dialog_content = "Después de escuchar que vendías esas cosas al comerciante, pensé que lo hacías por el dinero...",
  ui_story_30760601_1_123_dialog_content = "Pero usar dinero sucio... ¿para construir un palacio? En cualquier caso, al menos ahora sé que el dinero no es sucio.",
  ui_story_30760601_1_124_dialog_content = "El festival.",
  ui_story_30760601_1_125_dialog_content = "El Soberano del Océano sigue siendo un festival, después de todo.",
  ui_story_30760601_1_126_dialog_content = "Eh... Soy consciente de que es un festival. ¿Qué clase de respuesta es esa?",
  ui_story_30760601_1_127_dialog_content = "No seamos apresurados. Cuando se trata de los ideales de uno, hay que describirlos con todo detalle para influir en los corazones de los demás.",
  ui_story_30760601_1_128_dialog_content = "Había una vez, un héroe...",
  ui_story_30760601_1_129_dialog_content = "Navegaba por alta mar en un barco real, en busca de un tesoro legendario...",
  ui_story_30760601_1_130_dialog_content = "Cuando un día, se encontró con un monstruo marino gigante y blanco.",
  ui_story_30760601_1_131_dialog_content = "Y con él, descubrió un magnífico palacio submarino.",
  ui_story_30760601_1_132_dialog_content = "Por fin había encontrado su tesoro, así que hizo un pacto con la criatura blanca para exterminar a los violentos monstruos marinos que plagaban las aguas.",
  ui_story_30760601_1_133_dialog_content = "Esta es una de mis historias favoritas. Se llama <color=#FFB400>”Viaje de un Aventurero.”</color>",
  ui_story_30760601_1_134_dialog_content = "¿Un palacio de una historia?¿Pero no es \"Viaje de un Aventurero\" una obra de ficción?",
  ui_story_30760601_1_135_dialog_content = "¿O está diciendo que tiene algo que ver con el Soberano del Océano?",
  ui_story_30760601_1_136_dialog_content = "La razón por la que he venido aquí es para investigar la relación entre ambos.",
  ui_story_30760601_1_137_dialog_content = "Para ver ese palacio de la historia.",
  ui_story_30760601_1_138_dialog_content = "Mientras ofrezca mi sinceridad al Neptuno, él concederá mi deseo y hará que el palacio aparezca ante mí.",
  ui_story_30760601_1_139_dialog_content = "Ayudar a todos a dirigir el Soberano del Océano sin problemas es una forma de mostrar mi sinceridad.",
  ui_story_30760601_1_140_dialog_content = "Suena un poco impreciso...",
  ui_story_30760601_1_141_dialog_content = "¿Crees que esa historia está basada en la realidad? ¿O crees que no existe un palacio submarino?",
  ui_story_30760601_1_142_option_content = "Nunca había leído esa historia.",
  ui_story_30760601_1_143_dialog_content = "...",
  ui_story_30760601_1_144_dialog_content = "...",
  ui_story_30760601_1_145_dialog_content = "Qué extraño. De repente no tengo idea de como continuar en este tema.",
  ui_story_30760601_1_146_dialog_content = "Pero eso está bien. No importa si no has leído esa historia.",
  ui_story_30760601_1_147_option_content = "Yo lo creo.",
  ui_story_30760601_1_148_dialog_content = "Podría ser que el palacio de la historia sea un lugar real.",
  ui_story_30760601_1_149_dialog_content = "Me alegro de que puedas responder y creer en ello tan fácilmente.",
  ui_story_30760601_1_150_dialog_content = "Sólo espero que los regalos que he preparado no te decepcionen.",
  ui_story_30760601_1_151_dialog_content = "¿Regalos?",
  ui_story_30760601_1_152_dialog_content = "Correcto. No es todos los días que encuentro a alguien tan interesado en mis ideales.",
  ui_story_30760601_1_153_dialog_content = "Es solo propio expresar mi gratitud.",
  ui_story_30760601_1_154_option_content = "No lo creo para nada.",
  ui_story_30760601_1_155_dialog_content = "Esa historia es una obra de ficción, ¿no?",
  ui_story_30760601_1_156_dialog_content = "Cuando la gente escribe historias de así, a menudo alude involuntariamente a hechos reales.",
  ui_story_30760601_1_157_dialog_content = "La historia en sí puede ser ficticia, pero es muy posible que el autor haya inventado el relato basándose en varios relatos reales.",
  ui_story_30760601_1_158_dialog_content = "Es uno de mis ideales. A veces está lejos de mí, a veces está muy cerca.",
  ui_story_30760601_1_159_dialog_content = "En la leyenda del Soberano del Océano, se menciona un castillo.",
  ui_story_30760601_1_160_dialog_content = "El castillo en la leyenda, y el palacio en la historia... Puede haber algún tipo de relación entre los dos.",
  ui_story_30760601_1_161_dialog_content = "En cualquier caso, quiero que lo veas por ti mismo, también. Es por eso pedí tu ayuda.",
  ui_story_30760601_1_162_dialog_content = "Aunque, parece que el tiempo no es adecuado... Ah, bueno, supongo que podría esforzarme un poco más.",
  ui_story_30760601_1_163_dialog_content = "El palacio en el fondo del mar...",
  ui_story_30760601_1_164_dialog_content = "Aunque todo lo que queda son ruinas, sigue siendo una vista asombrosa para contemplar...",
  ui_story_30760601_1_165_dialog_content = "Un testamento de una grandiosa y brillante civilización que alguna vez vivió aquí.",
  ui_story_30760601_1_166_dialog_content = "¿El palacio? ¿Tu...? ¿Realmente invocaste al palacio submarino?",
  ui_story_30760601_1_167_dialog_content = "¿Qué piensas?¿Crees en su existencia ahora?",
  ui_story_30760601_1_168_dialog_content = "Sí, yo...",
  ui_story_30760601_1_169_dialog_content = "Por cierto, esto es sólo un espejismo. Si miras más de cerca, verás a través de mi artimaña.",
  ui_story_30760601_1_170_dialog_content = "Estaba a punto de decir que ahora creo en ello... Pero entonces me cortaste.",
  ui_story_30760601_1_171_dialog_content = "Eh... Por favor no se enojen. Hacer espejismos para que las veas es sólo uno de mis muchos poderes.",
  ui_story_30760601_1_172_dialog_content = "Desafortunadamente, no puedo aguantar más. Después de todo, estoy muy débil ahora.",
  ui_story_30760601_1_173_dialog_content = "Espera un minuto, estabas descansando muy cómodamente cuando volví...",
  ui_story_30760601_1_174_dialog_content = "Incluso te cambiaste a un traje de baño de quién sabe dónde...",
  ui_story_30760601_1_175_dialog_content = "¿Y aún eres capaz de usar tus poderes así?",
  ui_story_30760601_1_176_dialog_content = "Encima de eso, los demás me dijeron que el trabajo de hoy era fácil, según tu...",
  ui_story_30760601_1_177_dialog_content = "¿De verdad estás tan débil ahora?",
  ui_story_30760601_1_178_dialog_content = "Hmm. Parece que te empeñas en sobre-analizar las cosas...",
  ui_story_30760601_1_179_dialog_content = "Ey...¿No estabas de pie hace un segundo?",
  ui_story_30760601_1_180_dialog_content = "Espera, rayos...¿Por qué tengo la sensación de que vas a engañarme de nuevo?",
  ui_story_30760601_1_181_dialog_content = "Hmm, aunque mis fuerzas están casi agotadas, supongo que podría resistir.",
  ui_story_30760601_1_182_dialog_content = "Por lo menos, me gustaría darte un vistazo al palacio que sueño con ver.",
  ui_story_30760601_1_183_dialog_content = "Bien, bien, siento haberte malinterpretado de nuevo... Pensé que aún te quedaban fuerzas, pero supongo que no.",
  ui_story_30760601_1_184_dialog_content = "Nunca pensé que pudieras ser tan decidido...",
  ui_story_30760601_1_185_dialog_content = "Considéralo tu compensación.",
  ui_story_30760601_1_186_dialog_content = "¿Eh?",
  ui_story_30760601_1_187_dialog_content = "Simple y precipitado a veces, pero con una cierta perspicacia que roza lo anormal.",
  ui_story_30760601_1_188_dialog_content = "Tiene el aire de un héroe.",
  ui_story_30760601_1_189_dialog_content = "Y un héroe es todo lo que necesita esta historia para estar completa.",
  ui_story_30760601_1_190_dialog_content = "Como compensación por ayudarme a entregar esa mercancía, he decidido dejarle ver estas espectaculares vistas.",
  ui_story_30760601_1_191_dialog_content = "De esta manera, tampoco tengo que pagarte en efectivo.",
  ui_story_30760601_1_192_dialog_content = "...",
  ui_story_30760601_1_193_dialog_content = "Realmente no tenías que decir esa última parte, Kleken...",
  ui_story_30760601_1_194_dialog_content = "¿En serio? Pero pensé que mientras recibieras tu compensación, ¿estarías dispuesto a ayudarme a terminar el resto de mi trabajo?",
  ui_story_30760601_1_195_dialog_content = "¡¿Así que realmente quieres que siga haciendo recados para ti?! ¡¿No puedes dejar que ese sentimiento dure un poco más?!",
  ui_story_30760601_1_196_dialog_content = "Por supuesto que no puedo.",
  ui_story_30760601_1_197_dialog_content = "\"La Entrega Heroica\"...También es una historia muy interesante, ¿no crees?",
  ui_story_30760601_1_198_dialog_content = "¡¡Esa no es una historia real!!",
  ui_story_30760601_1_199_dialog_content = "Se me acaba de ocurrir, en realidad. ¡Espero que la disfrutes!"
}
return config
